for r in (dossier, rec):           # la ligne initiale et la ligne courante, même sans Dossier renseigné
  if r not in versions:
    versions.append(r)
versions.sort(key=lambda r: (r.Cree_le is not None, r.Cree_le, r.id))
position = versions.index(rec)
if position == 0:
  return $Description or ""         # signalement initial : rien à comparer
precedente = versions[position - 1]

# 2. Comparer mot à mot avec sa description
jetons = lambda t: re.findall(r"\*\*|\s+|\w+|[^\w\s]", t)
BORD = " \t\n,.;:!?)(«»\"'-–—"      # ponctuation et espaces laissés hors du surlignage

def surligner(morceaux):
  # Entoure de == chaque suite de mots ajoutés ; ponctuation en bordure et ** restent dehors
  sortie, groupe = [], []
  def fermer():
    if groupe:
      texte = "".join(groupe)
      coeur = texte.strip(BORD)
      if coeur:
        i = texte.index(coeur)
        sortie.append(texte[:i] + "==" + coeur + "==" + texte[i + len(coeur):])
      else:
        sortie.append(texte)
      del groupe[:]
  for j in morceaux:
    if j == "**":
      fermer()
      sortie.append(j)
    else:
      groupe.append(j)
  fermer()
  return "".join(sortie)

